-- Source-verified IPA 2020-12-13 logic, timing, network and nonfunctional requirements.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q02','exam-fe','集合演算','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問2・改編】全体集合S内の集合A、Bについて、補集合を¬、和集合を∪、積集合を∩、差集合を−とする。¬A ∩ ¬Bと等しいものはどれか。','[{"id":"a","text":"¬A − B"},{"id":"b","text":"(¬A ∪ ¬B) − (A ∩ B)"},{"id":"c","text":"(S − A) ∪ (S − B)"},{"id":"d","text":"S − (A ∩ B)"}]','"a"','¬A − B = ¬A ∩ ¬B。ド・モルガンの法則からS − (A ∪ B)とも等しい。 中文：从A的补集中除去B，等于同时不属于A和B。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q12','exam-fe','多重割込み','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問12・改編】0〜5msの間にメイン処理と割込みを単一CPUで実行する。割込みAは優先度高・処理0.5msで時刻1、2.5、3.5msに発生。Bは優先度低・処理1.5msで時刻0、5msに発生。多重割込みを許可し、呼出し・復帰のオーバーヘッドを無視するとき、0〜5msでメイン処理が利用できる時間は何msか。','[{"id":"a","text":"2"},{"id":"b","text":"2.5"},{"id":"c","text":"3.5"},{"id":"d","text":"5"}]','"a"','Bは0〜1msと1.5〜2msに計1.5ms実行、Aは3回で計1.5ms。5ms時点の新たなBは範囲外で、残り2msがメイン処理。 中文：该区间内B共1.5ms，A共1.5ms，主处理使用2ms。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q22','exam-fe','論理回路','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問22・改編】二つの入力A、Bがある。Aを反転した信号とBをANDし、別にAとBをANDし、両方の出力をORした信号をFとする。Fと等しい論理式はどれか。','[{"id":"a","text":"F = A"},{"id":"b","text":"F = B"},{"id":"c","text":"F = A ∧ B"},{"id":"d","text":"F = A ∨ B"}]','"b"','F = (¬A ∧ B) ∨ (A ∧ B) = B ∧ (¬A ∨ A) = B。 中文：两个与门分别为非A且B、A且B；或起来可化简为B。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q52','exam-fe','アローダイアグラム','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問52・改編】次の作業ネットワークについて、開始日を1日目とする。各矢印の数字は所要日数、0はダミー作業。開始→節点1はA(5日)、開始→節点2はB(10日)、節点2→節点1は0日、節点1→節点3はC(20日)、節点3→節点5はG(20日)、節点1→節点5はD(30日)、節点1→節点4はE(10日)、節点2→節点4はF(10日)、節点4→節点5は0日、節点5→終了はH(10日)。適切な記述はどれか。','[{"id":"a","text":"Cを最も早く開始できるのは6日目"},{"id":"b","text":"Dはクリティカルパス上の作業"},{"id":"c","text":"Eの総余裕時間は30日"},{"id":"d","text":"Fを最も遅く開始できるのは11日目"}]','"c"','最長経路はB→ダミー→C→G→Hの60日。節点1の最早時刻10、節点5の最遅時刻50なので、Eの総余裕は50−10−10=30日。 中文：关键路径为B、虚作业、C、G、H，共60天；E总时差30天。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q53','exam-fe','要員計画','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問53・改編】10人が0.5kステップ／人日で作業すると30日かかる開発がある。10日終了時点の完成量は合計30kステップ。残りを予定の30日以内に終えるには、同じ生産性の要員を少なくとも何人追加する必要があるか。','[{"id":"a","text":"2人"},{"id":"b","text":"7人"},{"id":"c","text":"10人"},{"id":"d","text":"20人"}]','"c"','予定総量は10×0.5×30=150k。実績30kを10人×10日で割ると実際の生産性は0.3k／人日。残り120kを20日で処理するには120÷(0.3×20)=20人、追加10人。 中文：原计划总量150k；实际每人每天完成0.3k，剩余120k需20人工作20天，所以再增加10人。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q64','exam-fe','非機能要件','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問64・改編】非機能要件を定義する際に行う作業はどれか。','[{"id":"a","text":"業務を構成する機能間のデータの流れを明確化する"},{"id":"b","text":"開発に用いる言語に応じた開発基準や標準の技術要件を作成する"},{"id":"c","text":"システム機能として実現する範囲を定義する"},{"id":"d","text":"他システムとの情報授受などのインタフェースを明確化する"}]','"b"','公式問題では、機能そのものの範囲・情報の流れ・授受に対し、開発基準や標準技術要件の定義を非機能側の作業としている。 中文：依题目的区分，开发标准及技术要求属于非功能方面，其他选项描述功能范围和信息交互。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
